(function(){
  'use strict';

  const CLOSED=['Approved','Closed'];
  const MAIN_STREAMS=['M2O','O2C','F2P','P2P','S2P','W2D','R2R'];
  const e=v=>typeof esc==='function'?esc(v):String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const d=()=>typeof data==='function'?data():{};
  const plan=()=>state.planning||(state.planning={planVersion:'',budget:{},timeEntries:[]});
  const tasks=()=>state.tasks?.tasks||(state.tasks={tasks:[]}).tasks;
  const milestones=()=>state.milestones?.milestones||(state.milestones={milestones:[]}).milestones;
  const fmtHours=n=>`${Math.round((Number(n)||0)*10)/10}h`;
  const money=(n,currency='CAD')=>Number.isFinite(Number(n))&&String(n)!==''?new Intl.NumberFormat('en-CA',{style:'currency',currency,maximumFractionDigits:0}).format(Number(n)):'—';
  const num=v=>Number(v)||0;
  const pct=v=>Math.max(0,Math.min(100,Number(v)||0));
  const weekStartIso=(input)=>{const x=input?new Date(`${input}T12:00:00`):new Date(),day=x.getDay(),diff=(day===0?-6:1-day);x.setDate(x.getDate()+diff);return x.toISOString().slice(0,10)};
  const streamDef=id=>(state.framework?.valueStreams||[]).find(s=>s.id===id)||(state.framework?.crossFunctional||[]).find(s=>s.id===id);
  const ownerRole=name=>{if(name===state.framework?.businessOwner?.name||name==='Alex'||name==='Business Owner')return 'Business Owner';return (state.framework?.people||[]).find(p=>p.name===name)?.role||'SME / Other'};
  const round4=n=>Math.max(4,Math.round(Number(n||0)/4)*4);

  function copyFields(target,source,keys){keys.forEach(k=>{if(Object.prototype.hasOwnProperty.call(source,k))target[k]=source[k]})}
  function datePatch(target,p){copyFields(target,p,['start','due','baselineDue','forecastDue','phase','dependency','milestoneId','type','priority','estimatedHours','expectedOutcome','milestoneOutcome','entityScope','sourceType']);if(p.due&&!p.baselineDue)target.baselineDue=p.due;if(p.due&&!p.forecastDue)target.forecastDue=p.due;target.due=target.forecastDue||target.baselineDue||target.due||''}
  function baseTask(id,title,stream,owner,role){return {id,title,stream,l1:stream,process:'All',owner,ownerRole:role,status:'Not Started',priority:'High',progress:0,start:'',due:'',baselineDue:'',forecastDue:'',phase:'',dependency:'',milestoneId:'',ganttOrder:0,type:'Activity',l2:'',l3ProcessId:'',l3ProcessName:'',entityScope:'All entities',milestoneContribution:'',estimatedHours:'',sourceType:'Program readiness plan',sourceId:'',sourceTitle:'',sourceLevel:'L1',blocker:'',milestoneOutcome:'',expectedOutcome:'',completedBy:'',completedAt:'',approvedBy:'',approvedAt:''}}

  function applyPlanningSeed(){
    const p=plan(),version=p.planVersion;if(!version)return;
    if(window.__v27StateTaskRef!==state.tasks||window.__v27StateMilestoneRef!==state.milestones){
      window.__v27StateTaskRef=state.tasks;window.__v27StateMilestoneRef=state.milestones;
      window.__v27OriginalBase={tasks:clone(state.tasks),milestones:clone(state.milestones),planning:clone(state.planning)};
    }
    (p.milestonePatches||[]).forEach(mp=>{const m=milestones().find(x=>x.id===mp.id);if(!m||m.schedulePlanVersion===version)return;copyFields(m,mp,['start','end','status']);m.schedulePlanVersion=version;m.scheduleBasis='Initial planning assumption — adjust to actual implementation sequencing.'});

    const tarr=tasks(),m1=p.m1Templates||{};
    MAIN_STREAMS.filter(s=>s!=='M2O').forEach(stream=>{
      ['001','002'].forEach(suffix=>{const t=tarr.find(x=>x.id===`T-${stream}-${suffix}`),tpl=m1[suffix];if(!t||!tpl||t.planSeedVersion===version)return;const keep={id:t.id,stream:t.stream,l1:t.l1||t.stream,owner:t.owner,ownerRole:t.ownerRole,status:t.status,progress:t.progress,ganttOrder:t.ganttOrder};datePatch(t,tpl);Object.assign(t,keep);t.planSeedVersion=version;t.planningBasis='Copied from Diane Madeiros M-01 planning assumptions at Business Owner request.'});
    });

    const templates=p.streamTaskTemplates||[],factors=p.streamFactors||{};
    MAIN_STREAMS.forEach((stream,si)=>{const sd=streamDef(stream),owner=sd?.bpo||'',role='BPO',factor=Number(factors[stream])||1;
      templates.forEach((tpl,ti)=>{const id=`T-${stream}-${tpl.suffix}`;let t=tarr.find(x=>x.id===id);if(t?.planSeedVersion===version)return;if(!t){t=baseTask(id,tpl.title,stream,owner,role);tarr.push(t)}
        const keep={id:t.id,stream,l1:stream,owner:t.owner||owner,ownerRole:t.ownerRole||role,status:t.status||'Not Started',progress:num(t.progress)};
        Object.assign(t,{title:tpl.title,priority:tpl.priority||'High',type:tpl.type||'Activity',process:'All',entityScope:'All entities',sourceType:'Program readiness plan',sourceId:`PLAN-${version}`,sourceTitle:`December 2027 readiness workplan · ${stream}`});
        datePatch(t,{...tpl,estimatedHours:round4(num(tpl.baseHours)*factor),dependency:tpl.dependencySuffix?`T-${stream}-${tpl.dependencySuffix}`:''});Object.assign(t,keep);
        t.ganttOrder=t.ganttOrder||((Number(String(tpl.milestoneId||'M-00').replace(/\D/g,''))||0)*1000+(si+1)*100+ti+1);t.planSeedVersion=version;t.planningBasis='Initial Business Owner planning assumption — replace with actual dates/effort as implementation sequencing becomes clear.';
      });
    });

    (p.crossFunctionalTasks||[]).forEach((src,i)=>{let t=tarr.find(x=>x.id===src.id);if(t?.planSeedVersion===version)return;if(!t){t=baseTask(src.id,src.title,src.stream,src.owner,src.ownerRole);tarr.push(t)}const keep={status:t.status||'Not Started',progress:num(t.progress)};Object.assign(t,src,keep,{l1:src.stream,process:'All',entityScope:'All entities',baselineDue:src.due,forecastDue:src.due,due:src.due,ganttOrder:t.ganttOrder||5000+i*10,sourceType:'Program readiness plan',sourceId:`PLAN-${version}`,sourceLevel:'L1',planSeedVersion:version,planningBasis:'Initial Business Owner planning assumption — adjust to actual reality.'})});

    (p.businessOwnerPatches||[]).forEach(src=>{const t=tarr.find(x=>x.id===src.id);if(!t||t.planSeedVersion===version)return;datePatch(t,src);t.planSeedVersion=version;t.planningBasis='Initial Business Owner planning assumption — adjust to actual reality.'});
    (p.businessOwnerNewTasks||[]).forEach(src=>{let t=tarr.find(x=>x.id===src.id);if(t?.planSeedVersion===version)return;if(!t){t=baseTask(src.id,src.title,src.stream,src.owner,src.ownerRole);tarr.push(t)}Object.assign(t,src,{planSeedVersion:version,planningBasis:'Initial Business Owner planning assumption — adjust to actual reality.'})});
    (p.costTaskPatches||[]).forEach(src=>{const t=tarr.find(x=>x.id===src.id);if(!t||t.planSeedVersion===version)return;datePatch(t,src);t.planSeedVersion=version;t.planningBasis='Initial Business Owner planning assumption — adjust to actual reality.'});
  }

  function timeEntries(){const p=plan();return p.timeEntries||(p.timeEntries=[])}
  function budget(){const p=plan();return p.budget||(p.budget={currency:'CAD',approvedBudget:'',personRates:{},lines:[]})}
  function rateFor(person){return num(budget().personRates?.[person])}
  function actualHoursForTask(id){return timeEntries().filter(x=>x.taskId===id).reduce((s,x)=>s+num(x.hours),0)}
  function actualHoursForPerson(name){return timeEntries().filter(x=>x.person===name).reduce((s,x)=>s+num(x.hours),0)}
  function actualLaborCost(){return timeEntries().reduce((s,x)=>s+num(x.hours)*rateFor(x.person),0)}
  function plannedLaborCost(){return tasks().reduce((s,t)=>s+num(t.estimatedHours)*rateFor(t.owner),0)}
  function manualActual(){return (budget().lines||[]).reduce((s,x)=>s+num(x.actual),0)}
  function manualForecast(){return (budget().lines||[]).reduce((s,x)=>s+num(x.forecast),0)}
  function manualBudget(){return (budget().lines||[]).reduce((s,x)=>s+num(x.budget),0)}
  function plannedHours(){return tasks().reduce((s,t)=>s+num(t.estimatedHours),0)}
  function loggedHours(){return timeEntries().reduce((s,x)=>s+num(x.hours),0)}
  function missingRatePeople(){return [...new Set([...tasks().filter(t=>num(t.estimatedHours)>0).map(t=>t.owner),...timeEntries().filter(x=>num(x.hours)>0).map(x=>x.person)].filter(Boolean))].filter(x=>!rateFor(x))}
  function planTarget(){return plan().readinessTarget||'2027-12-22'}

  function budgetKpis(){const b=budget(),currency=b.currency||'CAD',approved=num(b.approvedBudget),forecast=manualForecast()+plannedLaborCost(),actual=manualActual()+actualLaborCost(),missing=missingRatePeople();return `<div class="v27-kpis"><div class="card"><span>Readiness target</span><b>${e(planTarget())}</b><small>business readiness baseline</small></div><div class="card"><span>Planned effort</span><b>${fmtHours(plannedHours())}</b><small>task estimates across the plan</small></div><div class="card"><span>Actual effort</span><b>${fmtHours(loggedHours())}</b><small>weekly hours logged by the team</small></div><div class="card"><span>Approved budget</span><b>${approved?money(approved,currency):'Not entered'}</b><small>${manualBudget()?`${money(manualBudget(),currency)} categorized`: 'enter when approved'}</small></div><div class="card"><span>Forecast economic cost</span><b>${missing.length?'Rates incomplete':money(forecast,currency)}</b><small>${missing.length?`${missing.length} person rate${missing.length===1?'':'s'} missing`:'manual forecast + planned internal effort'}</small></div><div class="card"><span>Actual economic cost</span><b>${missing.length?'Rates incomplete':money(actual,currency)}</b><small>manual actual + logged internal effort</small></div></div>`}

  function weeklyRows(){const map=new Map();timeEntries().forEach(x=>{const k=x.weekStart||weekStartIso(x.date);const z=map.get(k)||{week:k,hours:0,people:new Set(),outputs:0};z.hours+=num(x.hours);z.people.add(x.person);if(String(x.output||'').trim())z.outputs++;map.set(k,z)});return [...map.values()].sort((a,b)=>String(b.week).localeCompare(String(a.week)))}
  function weeklySummary(){const rows=weeklyRows();return `<div class="v27-week-grid">${rows.slice(0,12).map(r=>`<div class="v27-week card"><span>Week of ${e(r.week)}</span><b>${fmtHours(r.hours)}</b><small>${r.people.size} contributor${r.people.size===1?'':'s'} · ${r.outputs} documented output${r.outputs===1?'':'s'}</small></div>`).join('')||'<div class="card empty">No weekly hours have been logged yet.</div>'}</div>`}

  function taskEffortTable(){const rows=tasks().filter(t=>num(t.estimatedHours)>0||actualHoursForTask(t.id)>0).slice().sort((a,b)=>String(a.milestoneId||'').localeCompare(String(b.milestoneId||''))||String(a.stream||'').localeCompare(String(b.stream||''))||String(a.title||'').localeCompare(String(b.title||'')));return `<div class="v27-table-wrap"><table class="v27-table"><thead><tr><th>Task / output</th><th>Milestone</th><th>Stream</th><th>Owner</th><th>Est.</th><th>Actual</th><th>Progress</th><th>Effort vs estimate</th></tr></thead><tbody>${rows.map(t=>{const est=num(t.estimatedHours),act=actualHoursForTask(t.id),ratio=est?100*act/est:0;return `<tr data-edit-task="${e(t.id)}"><td><b>${e(t.title)}</b><small>${e(t.expectedOutcome||'Expected outcome not documented')}</small></td><td>${e(t.milestoneId||'—')}</td><td>${e(t.stream||'Program')}</td><td>${e(t.owner||'Unassigned')}</td><td>${fmtHours(est)}</td><td><b>${fmtHours(act)}</b></td><td>${Math.round(pct(typeof taskProgress==='function'?taskProgress(t):t.progress))}%</td><td><div class="v27-effortbar"><i style="width:${Math.min(100,ratio)}%"></i></div><small>${est?`${Math.round(ratio)}% of estimate used`:'No estimate'}</small></td></tr>`}).join('')}</tbody></table></div>`}

  function milestoneEffortTable(){const rows=milestones().map(m=>{const mt=tasks().filter(t=>t.milestoneId===m.id),est=mt.reduce((s,t)=>s+num(t.estimatedHours),0),act=mt.reduce((s,t)=>s+actualHoursForTask(t.id),0),done=mt.length?mt.reduce((s,t)=>s+pct(typeof taskProgress==='function'?taskProgress(t):t.progress),0)/mt.length:0;return {m,est,act,done,count:mt.length}});return `<div class="v27-table-wrap"><table class="v27-table"><thead><tr><th>Milestone</th><th>Dates</th><th>Tasks</th><th>Planned hours</th><th>Actual hours</th><th>Avg. task progress</th><th>Readiness signal</th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${e(x.m.id)} · ${e(x.m.name)}</b></td><td>${e(x.m.start||'')} → ${e(x.m.end||'')}</td><td>${x.count}</td><td>${fmtHours(x.est)}</td><td><b>${fmtHours(x.act)}</b></td><td>${Math.round(x.done)}%</td><td>${x.m.end&&x.m.end<=planTarget()?'Supports Dec-2027 readiness':'Post-readiness / go-live'}</td></tr>`).join('')}</tbody></table></div>`}

  function timeEntryTable(){const rows=timeEntries().slice().sort((a,b)=>String(b.weekStart||'').localeCompare(String(a.weekStart||''))||String(a.person||'').localeCompare(String(b.person||'')));return `<div class="v27-table-wrap"><table class="v27-table"><thead><tr><th>Week</th><th>Person</th><th>Task</th><th>Stream</th><th>Hours</th><th>Output received</th><th>Notes</th></tr></thead><tbody>${rows.map(x=>{const t=tasks().find(t=>t.id===x.taskId);return `<tr data-v27-time="${e(x.id)}"><td>${e(x.weekStart)}</td><td><b>${e(x.person)}</b><small>${e(x.role||ownerRole(x.person))}</small></td><td>${x.taskId?`<b>${e(x.taskId)}</b><small>${e(t?.title||'')}</small>`:'Program / admin'}</td><td>${e(x.stream||t?.stream||'Program')}</td><td><b>${fmtHours(x.hours)}</b></td><td class="v27-output">${e(x.output||'')}</td><td>${e(x.notes||'')}</td></tr>`}).join('')||'<tr><td colspan="7" class="empty">No time entries yet. Use “Log weekly hours” to start the actual-effort history.</td></tr>'}</tbody></table></div>`}

  function budgetLinesTable(){const b=budget(),c=b.currency||'CAD';return `<div class="v27-table-wrap"><table class="v27-table"><thead><tr><th>Category</th><th>Budget</th><th>Forecast</th><th>Actual</th><th>Owner</th><th>Notes</th></tr></thead><tbody>${(b.lines||[]).map(x=>`<tr data-v27-budget-line="${e(x.id)}"><td><b>${e(x.category)}</b><small>${e(x.id)}</small></td><td>${money(x.budget,c)}</td><td>${money(x.forecast,c)}</td><td>${money(x.actual,c)}</td><td>${e(x.owner||'')}</td><td>${e(x.notes||'')}</td></tr>`).join('')}</tbody><tfoot><tr><th>Manual spend total</th><th>${money(manualBudget(),c)}</th><th>${money(manualForecast(),c)}</th><th>${money(manualActual(),c)}</th><th></th><th>Internal effort cost is calculated separately from weekly hours × loaded rate.</th></tr></tfoot></table></div>`}

  function peopleRateTable(){const b=budget(),c=b.currency||'CAD',names=[...new Set([state.framework?.businessOwner?.name||'Alex',...(state.framework?.people||[]).map(p=>p.name),...tasks().map(t=>t.owner)].filter(Boolean))].sort();return `<div class="v27-table-wrap"><table class="v27-table"><thead><tr><th>Person</th><th>Role</th><th>Stream</th><th>Loaded rate</th><th>Planned hours</th><th>Actual hours</th><th>Planned internal cost</th><th>Actual internal cost</th></tr></thead><tbody>${names.map(name=>{const p=(state.framework?.people||[]).find(x=>x.name===name),rate=rateFor(name),ph=tasks().filter(t=>t.owner===name).reduce((s,t)=>s+num(t.estimatedHours),0),ah=actualHoursForPerson(name);return `<tr><td><b>${e(name)}</b></td><td>${e(p?.role||ownerRole(name))}</td><td>${e(p?.stream||'Program')}</td><td class="${rate?'':'v27-missing'}">${rate?`${money(rate,c)}/h`:'Not entered'}</td><td>${fmtHours(ph)}</td><td>${fmtHours(ah)}</td><td>${rate?money(rate*ph,c):'—'}</td><td>${rate?money(rate*ah,c):'—'}</td></tr>`}).join('')}</tbody></table></div>`}

  function renderBudget(){applyPlanningSeed();const b=budget(),missing=missingRatePeople();return `<div class="v27-budget"><div class="page-head"><div><h1>Budget & Effort Control</h1><p>Connect planned work, weekly actual hours and delivered outputs so project effort can be evaluated against the results received.</p></div><div class="button-row"><button class="btn" id="v27EditBudget">Budget & rates</button><button class="btn" id="v27ExportTime">Export time CSV</button><button class="btn primary" id="v27LogTime">+ Log weekly hours</button></div></div><div class="notice v27-assumption"><b>Planning assumption:</b> the dates and estimated hours through ${e(planTarget())} are an initial Business Owner planning baseline, not actuals. Update task dates and estimates as the implementation partner, BPOs and SMEs refine sequencing.</div>${budgetKpis()}${missing.length?`<div class="notice warning"><b>Cost view incomplete:</b> loaded hourly rates are missing for ${missing.map(e).join(', ')}. Hours remain fully trackable; cost KPIs will become complete when rates are entered.</div>`:''}<div class="section-title"><h2>Weekly effort</h2><span>actual hours and documented outputs</span></div>${weeklySummary()}<div class="section-title"><div><h2>Time log</h2><span>one row per person / week / task; output is required</span></div></div>${timeEntryTable()}<div class="section-title"><h2>Effort by task and output</h2><span>planned versus actual effort</span></div>${taskEffortTable()}<div class="section-title"><h2>Effort by milestone</h2><span>readiness work through December 2027</span></div>${milestoneEffortTable()}<div class="section-title"><h2>Project budget</h2><span>manual spend categories</span></div>${budgetLinesTable()}<div class="section-title"><h2>Internal effort valuation</h2><span>loaded rate × task / weekly hours</span></div>${peopleRateTable()}<div class="card pad v27-budget-notes"><h3>Budget notes</h3><p>${e(b.budgetNotes||'No budget notes entered.')}</p><p><b>Economic-cost convention:</b> calculated internal effort cost is shown separately from manually entered project spend. Avoid entering the same internal effort twice if a budget line already includes it.</p></div></div>`}

  function personOptions(current=''){const names=[...new Set([state.framework?.businessOwner?.name||'Alex',...(state.framework?.people||[]).map(p=>p.name),...tasks().map(t=>t.owner)].filter(Boolean))].sort();return names.map(x=>`<option value="${e(x)}" ${x===current?'selected':''}>${e(x)}</option>`).join('')}
  function taskOptions(current='',person=''){const xs=tasks().filter(t=>!person||t.owner===person||t.stream==='Program').slice().sort((a,b)=>String(a.milestoneId||'').localeCompare(String(b.milestoneId||''))||String(a.title||'').localeCompare(String(b.title||'')));return `<option value="">Program / admin</option>${xs.map(t=>`<option value="${e(t.id)}" ${t.id===current?'selected':''}>${e(t.id)} · ${e(t.title)}</option>`).join('')}`}

  function editTimeEntry(id){const arr=timeEntries(),x=arr.find(z=>z.id===id),t=x||{id:uid('TIME'),weekStart:weekStartIso(),person:'',role:'',taskId:'',stream:'Program',hours:'',output:'',notes:''};const m=modal(x?'Edit weekly time entry':'Log weekly project hours',`<div class="form-grid"><label>Week starting Monday<input type="date" name="weekStart" value="${e(t.weekStart||weekStartIso())}"></label><label>Person<select name="person" id="v27TimePerson"><option value="">Select person</option>${personOptions(t.person)}</select></label><label class="full">Task<select name="taskId" id="v27TimeTask">${taskOptions(t.taskId,t.person)}</select></label><label>Hours<input type="number" min="0.25" step="0.25" name="hours" value="${e(t.hours||'')}"></label><label>Stream<input name="stream" value="${e(t.stream||'Program')}"></label><label class="full">Output / result produced<textarea name="output" rows="3" placeholder="What was completed, decided, validated, documented or tested this week?">${e(t.output||'')}</textarea></label><label class="full">Notes / context<textarea name="notes" rows="2">${e(t.notes||'')}</textarea></label></div><div class="notice"><b>Control rule:</b> hours are not accepted without a documented output. This is what allows the Control Tower to compare effort consumed with the result received.</div>`);const person=m.querySelector('#v27TimePerson'),task=m.querySelector('#v27TimeTask');person.onchange=()=>{task.innerHTML=taskOptions('',person.value)};if(x){const del=document.createElement('button');del.className='btn danger';del.textContent='Delete';m.querySelector('.modal-actions').prepend(del);del.onclick=()=>{if(!confirm('Delete this time entry?'))return;state.planning.timeEntries=arr.filter(z=>z.id!==x.id);mark('planning');m.remove();render()}}m.querySelector('.modal-save').onclick=()=>{const v=vals(m),hours=num(v.hours),output=String(v.output||'').trim();if(!v.person){alert('Select a person.');return}if(hours<=0){alert('Enter hours greater than zero.');return}if(!output){alert('Document the output or result produced for these hours.');return}v.weekStart=weekStartIso(v.weekStart);const taskRec=tasks().find(z=>z.id===v.taskId);v.role=ownerRole(v.person);v.stream=taskRec?.stream||v.stream||'Program';v.output=output;v.createdAt=x?.createdAt||new Date().toISOString();v.updatedAt=new Date().toISOString();Object.assign(t,v);if(!x)arr.push(t);mark('planning');m.remove();render()}}

  function editBudgetSettings(){const b=budget(),names=[...new Set([state.framework?.businessOwner?.name||'Alex',...(state.framework?.people||[]).map(p=>p.name),...tasks().map(t=>t.owner)].filter(Boolean))].sort();const m=modal('Budget & loaded hourly rates',`<div class="form-grid"><label>Currency<input name="currency" value="${e(b.currency||'CAD')}"></label><label>Approved project budget<input type="number" min="0" step="1000" name="approvedBudget" value="${e(b.approvedBudget||'')}"></label><label class="full">Budget notes<textarea name="budgetNotes" rows="3">${e(b.budgetNotes||'')}</textarea></label></div><div class="section-title"><h2>Loaded hourly rates</h2><span>leave blank until a defendable rate is available</span></div><div class="v27-rate-editor">${names.map((name,i)=>`<label><span><b>${e(name)}</b><small>${e(ownerRole(name))}</small></span><input type="number" min="0" step="1" data-v27-rate-person="${e(name)}" value="${e(b.personRates?.[name]||'')}" placeholder="$/h"></label>`).join('')}</div><div class="notice"><b>Rate convention:</b> use the loaded internal project rate you want for economic-cost tracking. The dashboard intentionally does not invent salary or consulting rates.</div>`);m.querySelector('.modal-save').onclick=()=>{const v=vals(m);b.currency=v.currency||'CAD';b.approvedBudget=v.approvedBudget;b.budgetNotes=v.budgetNotes;b.personRates=b.personRates||{};m.querySelectorAll('[data-v27-rate-person]').forEach(x=>{const n=x.dataset.v27RatePerson,val=num(x.value);if(val>0)b.personRates[n]=val;else delete b.personRates[n]});mark('planning');m.remove();render()}}

  function editBudgetLine(id){const b=budget(),arr=b.lines||(b.lines=[]),x=arr.find(z=>z.id===id),z=x||{id:uid('BUD'),category:'',budget:'',forecast:'',actual:'',owner:'',notes:''};const m=modal(x?'Edit budget line':'Add budget line',`<div class="form-grid"><label class="full">Category<input name="category" value="${e(z.category||'')}"></label><label>Budget<input type="number" min="0" step="1000" name="budget" value="${e(z.budget||'')}"></label><label>Forecast<input type="number" min="0" step="1000" name="forecast" value="${e(z.forecast||'')}"></label><label>Actual<input type="number" min="0" step="1000" name="actual" value="${e(z.actual||'')}"></label><label>Owner<input name="owner" value="${e(z.owner||'')}"></label><label class="full">Notes<textarea name="notes" rows="3">${e(z.notes||'')}</textarea></label></div>`);if(x){const del=document.createElement('button');del.className='btn danger';del.textContent='Delete';m.querySelector('.modal-actions').prepend(del);del.onclick=()=>{if(!confirm('Delete this budget line?'))return;b.lines=arr.filter(a=>a.id!==x.id);mark('planning');m.remove();render()}}m.querySelector('.modal-save').onclick=()=>{Object.assign(z,vals(m));if(!x)arr.push(z);mark('planning');m.remove();render()}}

  function exportTimeCsv(){const header=['Week start','Person','Role','Task ID','Task','Stream','Milestone','Hours','Output','Notes'],rows=timeEntries().map(x=>{const t=tasks().find(z=>z.id===x.taskId);return [x.weekStart,x.person,x.role||ownerRole(x.person),x.taskId||'',t?.title||'',x.stream||t?.stream||'Program',t?.milestoneId||'',x.hours,x.output||'',x.notes||'']});const q=v=>`"${String(v??'').replace(/"/g,'""')}"`,csv=[header,...rows].map(r=>r.map(q).join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download=`D365-weekly-effort-${today()}.csv`;a.click();URL.revokeObjectURL(a.href)}

  function decorateTaskEffort(){document.querySelectorAll('tr[data-edit-task]').forEach(row=>{const id=row.dataset.editTask,t=tasks().find(x=>x.id===id);if(!t||row.querySelector('.v27-task-effort'))return;const act=actualHoursForTask(id),est=num(t.estimatedHours);if(!est&&!act)return;const cell=row.querySelector('td:nth-child(2)')||row.querySelector('td');if(!cell)return;const s=document.createElement('small');s.className='v27-task-effort';s.textContent=`Effort: ${act}h actual / ${est||'—'}h estimated`;cell.appendChild(s)})}
  function effortPulse(){const b=budget(),c=b.currency||'CAD',missing=missingRatePeople();return `<section class="v27-pulse"><div class="section-title"><div><h2>Effort & budget pulse</h2><span>planned effort → actual hours → output received</span></div><button class="btn" type="button" data-v27-open-budget>Open Budget & Effort</button></div><div class="v27-pulse-grid"><div class="card"><span>Planned effort</span><b>${fmtHours(plannedHours())}</b></div><div class="card"><span>Actual logged</span><b>${fmtHours(loggedHours())}</b></div><div class="card"><span>Outputs logged</span><b>${timeEntries().filter(x=>String(x.output||'').trim()).length}</b></div><div class="card"><span>Actual economic cost</span><b>${missing.length?'Rates incomplete':money(manualActual()+actualLaborCost(),c)}</b></div></div></section>`}

  const priorEditTask=editTask;
  editTask=function(id,stream=selectedStream,ownerDefault='',defaults={}){applyPlanningSeed();priorEditTask(id,stream,ownerDefault,defaults);const m=[...document.querySelectorAll('.modal-backdrop')].at(-1),t=tasks().find(x=>x.id===id);if(!m||!t)return;const body=m.querySelector('.modal-body');if(body&&!body.querySelector('.v27-task-actual')){const a=actualHoursForTask(t.id),est=num(t.estimatedHours),n=document.createElement('div');n.className='notice v27-task-actual';n.innerHTML=`<b>Effort to date:</b> ${a}h actual logged${est?` / ${est}h estimated (${Math.round(100*a/est)}%)`:''}. <button type="button" class="btn tiny" data-v27-log-from-task="${e(t.id)}">Log weekly hours</button>`;body.prepend(n);n.querySelector('[data-v27-log-from-task]').onclick=()=>{m.remove();const entry={};editTimeEntryForTask(t.id)}}}
  function editTimeEntryForTask(taskId){editTimeEntry();const m=[...document.querySelectorAll('.modal-backdrop')].at(-1),t=tasks().find(x=>x.id===taskId);if(!m||!t)return;const person=m.querySelector('[name="person"]'),task=m.querySelector('[name="taskId"]'),stream=m.querySelector('[name="stream"]');if(person){person.value=t.owner||'';person.dispatchEvent(new Event('change'))}if(task)task.value=t.id;if(stream)stream.value=t.stream||'Program'}

  if(typeof renderCockpit==='function'){const base=renderCockpit;renderCockpit=function(){applyPlanningSeed();return base()+effortPulse()}}
  if(typeof renderBusinessOwner==='function'){const base=renderBusinessOwner;renderBusinessOwner=function(){applyPlanningSeed();return base()+effortPulse()}}

  const previousBind=bindPage;
  bindPage=function(){previousBind();decorateTaskEffort();document.querySelectorAll('[data-v27-open-budget]').forEach(x=>x.onclick=()=>{view='budget';document.querySelectorAll('#mainNav button').forEach(b=>b.classList.toggle('active',b.dataset.view==='budget'));render()});$('#v27LogTime')?.addEventListener('click',()=>editTimeEntry());$('#v27EditBudget')?.addEventListener('click',editBudgetSettings);$('#v27ExportTime')?.addEventListener('click',exportTimeCsv);document.querySelectorAll('[data-v27-time]').forEach(x=>x.onclick=()=>editTimeEntry(x.dataset.v27Time));document.querySelectorAll('[data-v27-budget-line]').forEach(x=>x.onclick=()=>editBudgetLine(x.dataset.v27BudgetLine));const budgetSection=document.querySelector('.v27-budget .section-title h2');if(budgetSection?.textContent==='Project budget'&&!document.querySelector('#v27AddBudgetLine')){const b=document.createElement('button');b.id='v27AddBudgetLine';b.className='btn';b.textContent='+ Budget line';budgetSection.closest('.section-title').appendChild(b);b.onclick=()=>editBudgetLine()}}

  const previousRender=render;
  render=function(){applyPlanningSeed();if(view==='budget'){const app=$('#app');app.innerHTML=renderBudget();bindPage();return}previousRender();decorateTaskEffort()};
})();
